-- KOPIS 2026-11 snapshot, generated by script/kopis-seed/generate.py.
-- NOL evidence is separate: script/kopis-seed/nol-status.csv. Load after seed-local and seed-load.
WITH hall_source(kopis_hall, name, address, region, capacity) AS (VALUES
{{HALLS}}
), show_source(kopis_id, kopis_hall, title, genre, rating, guidance, minutes, performer,
               poster, registered_at, price, first_day, last_day, booking_open) AS (VALUES
{{SHOWS}}
), weekly(kopis_id, iso_day, start_time) AS (VALUES
{{PATTERNS}}
), halls AS MATERIALIZED (
    SELECT h.*, nextval(pg_get_serial_sequence('p_venues','id')) AS venue_id,
           nextval(pg_get_serial_sequence('p_venue_seat_grades','id')) AS grade_id FROM hall_source h
), shows AS MATERIALIZED (
    SELECT s.*, h.venue_id, h.grade_id, nextval(pg_get_serial_sequence('p_performances','id')) AS performance_id
    FROM show_source s JOIN halls h USING (kopis_hall)
), venues_insert AS (
    INSERT INTO p_venues (id, name, address, region, version, created_at, created_by, updated_at, updated_by)
    SELECT venue_id, name, address, region, 0, LOCALTIMESTAMP, 'KOPIS_SEED', LOCALTIMESTAMP, 'KOPIS_SEED' FROM halls
), grades_insert AS (
    INSERT INTO p_venue_seat_grades (id, venue_id, name, created_at, created_by, updated_at, updated_by)
    SELECT grade_id, venue_id, '일반', LOCALTIMESTAMP, 'KOPIS_SEED', LOCALTIMESTAMP, 'KOPIS_SEED' FROM halls
), seats_insert AS (
    -- One physical layout per KOPIS hall. Capacity is real; ten seats per row is a fixture.
    INSERT INTO p_venue_seats (venue_id, venue_seat_grade_id, section, row_label, seat_number,
                               created_at, created_by, updated_at, updated_by)
    SELECT venue_id, grade_id, 'A', ((n-1)/10+1)::text, (n-1)%10+1,
           LOCALTIMESTAMP, 'KOPIS_SEED', LOCALTIMESTAMP, 'KOPIS_SEED'
    FROM halls CROSS JOIN LATERAL generate_series(1, capacity) n
), performances_insert AS (
    INSERT INTO p_performances (id, seller_id, venue_id, title, genre, age_rating, age_guidance, running_time,
                                cast_info, poster_url, publication_status, operation_status, published_at, version,
                                created_at, created_by, updated_at, updated_by)
    SELECT performance_id, 1001, venue_id, title, genre, rating, guidance, minutes, performer, poster,
           'PUBLISHED', 'ACTIVE', registered_at::timestamp, 0,
           LOCALTIMESTAMP, 'KOPIS_SEED', LOCALTIMESTAMP, 'KOPIS_SEED' FROM shows
), prices_insert AS (
    INSERT INTO p_performance_grade_prices (performance_id, venue_seat_grade_id, price,
                                            created_at, created_by, updated_at, updated_by)
    SELECT performance_id, grade_id, price, LOCALTIMESTAMP, 'KOPIS_SEED', LOCALTIMESTAMP, 'KOPIS_SEED' FROM shows
), starts AS (
    SELECT s.performance_id, s.kopis_id, s.booking_open::timestamp AS opens,
           d::date+w.start_time::time AS start_at
    FROM shows s JOIN weekly w USING (kopis_id)
    CROSS JOIN LATERAL generate_series(s.first_day::date
            + ((w.iso_day - extract(isodow FROM s.first_day::date)::int + 7) % 7),
            s.last_day::timestamp, INTERVAL '7 days') d
)
-- Bulk read fixtures are not submitted to the seat worker. Keep the original two samples' normal setup.
INSERT INTO p_schedules (performance_id, start_at, booking_open_at, booking_close_at, operation_status,
                         seat_setup_status, seat_config_version, seat_setup_request_id, seat_setup_next_attempt_at,
                         sales_suspended, seat_setup_attempts, seat_setup_recovery_attempts, seat_setup_recovery_limit,
                         version, created_at, created_by, updated_at, updated_by)
SELECT performance_id, start_at, opens, start_at - INTERVAL '1 hour', 'ACTIVE',
       'PENDING', 1, gen_random_uuid()::text,
       CASE WHEN kopis_id IN ('PF305424','PF305396') THEN LOCALTIMESTAMP END,
       false, 0, 0, 0, 0, LOCALTIMESTAMP, 'KOPIS_SEED', LOCALTIMESTAMP, 'KOPIS_SEED'
FROM starts;
